import json,re
from pathlib import Path
base=Path('docs/live-run-records/codex-real-2026-10-31-001/calls/11_citation_verify/workspace')
stages=json.loads((base/'all_stages.json').read_text(encoding='utf-8-sig'))
verdict=json.loads((base/'verdict.json').read_text(encoding='utf-8-sig'))
listed=json.loads((base/'all_citations.json').read_text(encoding='utf-8-sig'))
found=[]; bases=[]; literals={}
pat=re.compile(r'(?:民事訴訟法|民法)第[0-9一二三四五六七八九十百]+條(?:之[0-9一二三四五六七八九十百]+)?(?:第[0-9一二三四五六七八九十百]+項)?|最高法院[0-9]+年度台上字第[0-9]+號(?:判決|裁定)?')
def walk(x,path):
    if isinstance(x,dict):
        for k,v in x.items():
            p=path+'.'+k
            if k in ('cited_statutes','cited_precedents','citations_used'):
                found.extend(v)
            if k=='legal_basis': bases.append((p,v))
            walk(v,p)
    elif isinstance(x,list):
        for i,v in enumerate(x):walk(v,f'{path}[{i}]')
    elif isinstance(x,str):
        for m in pat.finditer(x):
            literals.setdefault(m.group(),[]).append(path)
walk(stages,'stages');walk(verdict,'verdict')
