print('missing_from_provided',json.dumps(sorted(set(found)-set(listed)),ensure_ascii=False))
print('extra_in_provided',json.dumps(sorted(set(listed)-set(found)),ensure_ascii=False))
print('legal_basis_fields',json.dumps(bases,ensure_ascii=False))
print('additional_prose_refs',json.dumps({k:v for k,v in literals.items() if k not in listed},ensure_ascii=False))
print('judge_questions',json.dumps(stages['judge_questions'],ensure_ascii=False))
print('procedural_issues',json.dumps(verdict['mechanical_anchor_json']['procedural_issues'],ensure_ascii=False))
